from pathlib import Path
import json,re,math
import xml.etree.ElementTree as ET
from fontTools.svgLib.path import parse_path
from fontTools.pens.boundsPen import BoundsPen
from fontTools.pens.transformPen import TransformPen
ns='{http://www.w3.org/2000/svg}'
metadata=json.loads(Path('/app/out/margins.json').read_text())
assert set(metadata)=={'primary','stacked','icon'}
def translation(element):
    return tuple(map(float,re.fullmatch(r'translate\(([^,]+),([^\)]+)\)',element.get('transform')).groups()))
def close(a,b):
    assert math.isclose(a,b,rel_tol=0,abs_tol=1e-9),(a,b)
for name in metadata:
    assert set(metadata[name])=={'margin','reference'}
    before=Path('/app/lockups',name+'.svg').read_text()
    after=Path('/app/out',name+'.svg').read_text()
    # Exact source preservation apart from root canvas attributes and group transforms.
    def neutralize(text):
        return re.sub(r'(viewBox|width|height|transform)="[^"]*"',r'\1="CHECKED"',text)
    assert neutralize(before)==neutralize(after)
    src,dst=ET.fromstring(before),ET.fromstring(after)
    original_nodes,list_nodes=list(src.iter()),list(dst.iter())
    assert len(original_nodes)==len(list_nodes)
    shifts=[]
    pen=BoundsPen(None)
    for old,new in zip(original_nodes,list_nodes):
        assert old.tag==new.tag
        if old.tag==ns+'path':
            assert old.attrib==new.attrib
        elif old.tag==ns+'g':
            ox,oy=translation(old)
            nx,ny=translation(new)
            shifts.append((nx-ox,ny-oy))
            transformed=TransformPen(pen,(1,0,0,1,nx,ny))
            for path in new.findall(ns+'path'):
                parse_path(path.get('d'),transformed)
    for shift in shifts:
        close(shift[0],shifts[0][0]); close(shift[1],shifts[0][1])
    x0,y0,x1,y1=pen.bounds
    m=metadata[name]['margin']
    vx,vy,vw,vh=map(float,dst.get('viewBox').split())
    assert vx==vy==0
    for actual,expected in [(x0,m),(y0,m),(vw-x1,m),(vh-y1,m),(float(dst.get('width')),vw),(float(dst.get('height')),vh)]:
        close(actual,expected)
    print(f'{name}: margin={m}; viewBox={dst.get("viewBox")}; uniform translation={shifts[0]}; all checks passed')
print('Verified exact path content, path order, group structure, uniform translation, canvas dimensions, all four margins, and JSON schema.')
